script:
frappe.ui.form.on("Library Member", {

    refresh(frm) {
        frappe.msgprint("Welcome to Library Member Form!");
        if (frm.is_new()) {
            frappe.msgprint("Create a New Member");
        }
    },

    full_name(frm) {
        frm.set_value("full_name", frm.doc.full_name.toUpperCase());
    }
});

frappe.listview_settings["Library Member"] = {
    onload(listview) {
        frappe.show_alert({
            message: "Library Member List Loaded",
            indicator: "green"
        });
    },
    onload(listview) {
        listview.page.add_inner_button("Say Hello", function () {
            frappe.msgprint("Hello from List View!");
        });
    },
    onload(listview) {
        listview.page.add_inner_button("Selected Count", function () {
            let selected = listview.get_checked_items();
            frappe.msgprint(
                "Selected Members: " + selected.length
            );
        });
    },
    refresh(listview) {
        console.log("List Refreshed");
    }
};
